// AI: below section was generated by an AI
// Builds size tiers of fxsim: drops the FXS.add() registrations of effects outside a tier, lets terser remove the
// helpers that became unused, then gzips and smoke-tests each result.
// Usage: node tiers.js [--out <dir>]   (writes fxsim.js, fxsim.min.js, fxsim_<tier>.min.js and tiers.md)
"use strict";
const fs = require("fs"), path = require("path"), zlib = require("zlib"), vm = require("vm");
const NM = "C:/Users/DigvijayPatilLM/Downloads/WLED-main/WLED-main/node_modules/";
const acorn = require(NM + "acorn"), terser = require(NM + "terser");

const dir = __dirname;
const outArg = process.argv.indexOf("--out");
const out = outArg > 0 ? process.argv[outArg + 1] : path.join(dir, "dist");
fs.mkdirSync(out, { recursive: true });

const files = ["core.js", "fx_p1.js", "fx_p2.js", "fx_p3.js", "fx_p4.js", "fx_p5.js"];
const src = files.map(f => fs.readFileSync(path.join(dir, f), "utf8"));
const moods = (m => m.moods || m)(JSON.parse(fs.readFileSync(path.join(dir, "moods.json"), "utf8")));
const moodFx = [...new Set(moods.map(m => m.fx))];

// every registered name, per file, with the source range of its whole FXS.add(...) statement
function registrations(code) {
	const ast = acorn.parse(code, { ecmaVersion: 2022, sourceType: "script" });
	const regs = [];
	(function walk(n) {
		if (!n || typeof n.type !== "string") return;
		if (n.type === "ExpressionStatement" && n.expression.type === "CallExpression") {
			const c = n.expression.callee;
			if (c.type === "MemberExpression" && c.object.name === "FXS" && c.property.name === "add" && n.expression.arguments[0].type === "Literal") {
				regs.push({ name: n.expression.arguments[0].value, start: n.start, end: n.end });
				return;
			}
		}
		for (const k in n) { const v = n[k]; if (Array.isArray(v)) v.forEach(walk); else if (v && typeof v.type === "string") walk(v); }
	})(ast);
	return regs;
}

const regsPerFile = src.map((s, i) => i ? registrations(s) : []);
const all = regsPerFile.flat();
// audio = 'v' or 'f' in the WLED metadata flags (fxmeta.json, parsed from FX.cpp)
const meta = (m => m.fx || m.effects || m)(JSON.parse(fs.readFileSync(path.join(dir, "fxmeta.json"), "utf8")));
const audioNames = new Set(meta.filter(e => e.audio).map(e => e.name));

// keep(name) → bool; returns the concatenated source with the other registrations removed
function build(keep) {
	return src.map((s, i) => {
		const drop = regsPerFile[i].filter(r => !keep(r.name)).sort((a, b) => b.start - a.start);
		for (const r of drop) s = s.slice(0, r.start) + s.slice(r.end);
		return s;
	}).join("\n");
}

async function tier(id, label, keep) {
	const code = build(keep);
	const min = (await terser.minify(code, { ecma: 2020, compress: { passes: 3, unused: true, pure_getters: true }, mangle: true })).code;
	// smoke test: load in a fresh context, run each kept effect 200 frames at len 60
	const ctx = { module: undefined, console };
	vm.createContext(ctx);
	vm.runInContext(min + "\n;this.FXS = FXS;", ctx);
	const F = ctx.FXS, names = all.map(r => r.name).filter(keep);
	for (const n of names) {
		if (!F.has(n)) throw new Error(id + ": lost " + n);
		const seg = F.makeSeg({ fx: n, len: 60, pal: 11 });
		for (let f = 0; f < 200; f++) F.step(seg, 600000 + f * 23);
	}
	const gz = zlib.gzipSync(min, { level: 9 }).length;
	fs.writeFileSync(path.join(out, id === "all" ? "fxsim.min.js" : "fxsim_" + id + ".min.js"), min);
	return { id, label, effects: names.length, raw: Buffer.byteLength(code), min: Buffer.byteLength(min), gz };
}

(async () => {
	fs.writeFileSync(path.join(out, "fxsim.js"), build(() => true));
	const rows = [];
	rows.push(await tier("core", "Core only (every effect uses the fallback preview)", () => false));
	rows.push(await tier("moods", "Your mood effects (" + moodFx.length + ")", n => moodFx.includes(n)));
	rows.push(await tier("noaudio", "All effects without music effects", n => !audioNames.has(n)));
	rows.push(await tier("all", "All effects", () => true));
	const missing = moodFx.filter(n => !all.some(r => r.name === n));
	const t = ["| Tier | Effects | minified | minified + gzip |", "|---|---|---|---|"]
		.concat(rows.map(r => `| ${r.label} | ${r.effects} | ${(r.min / 1024).toFixed(1)} KB | **${(r.gz / 1024).toFixed(1)} KB** |`));
	const md = "# fxsim size tiers\n\nBuilt by tiers.js on " + new Date().toISOString() + ". Every tier was loaded and every kept effect was run for 200 frames.\n\n"
		+ t.join("\n") + "\n\nMood effects: " + moodFx.join(", ") + (missing.length ? "\n\nNOT ported: " + missing.join(", ") : "") + "\n";
	fs.writeFileSync(path.join(out, "tiers.md"), md);
	console.log(md);
})().catch(e => { console.error(e); process.exit(1); });
// AI: end
